/* =====================================================================
   TTRPG Shop - Data.sql
   Populates every table with sample data. Run after Tables.sql.
   Simulated period: 2023-11-01 to 2026-11-17.
   - Stock is consistent: Products.QuantityOnHand = purchased - sold.
   - Some prices increased on 2025-01-01, 2026-05-01, so UnitPrice /
     UnitCost on older order lines differ from the current Products prices.
   - Older editions (e.g. Player's Handbook (2014)) stop being restocked
     when their replacement launches and sell through remaining stock.
   ===================================================================== */

